// Emulates transpiler output (e.g. `tsc`/esbuild targeting ESM, as shipped in
// `@apollo/server/dist/esm/*`). The defining ingredient is the top-level
// `await`: if a CJS-style `const x = require(...)` prelude is injected into a
// module that also has top-level `await`, Node 22+ rejects it with
// ERR_AMBIGUOUS_MODULE_SYNTAX. A correct `import ... from "..."` prelude does
// not, which is exactly what this fixture exists to lock in.
const __dep = await import('node:os')

class Foo {
  async doStuff() {
    return 'doing stuff' + __dep.EOL.slice(0, 0)
  }
}

export default Foo
